-- ==============================================================================
-- DeV Fit: Seed Database Esercizi Completo (135+ Esercizi Autentici)
-- Include categorizzazione anatomica, attrezzatura e istruzioni dettagliate
-- ==============================================================================

-- 1. Assicura che la tabella exercises esista con tutte le colonne necessarie
CREATE TABLE IF NOT EXISTS exercises (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  muscle_group TEXT NOT NULL,
  secondary_muscles TEXT[] DEFAULT '{}',
  equipment TEXT NOT NULL,
  instructions TEXT,
  video_url TEXT,
  tracking_type TEXT DEFAULT 'weight_reps',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Inserimento o aggiornamento di tutti i 135+ esercizi
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  muscle_group = EXCLUDED.muscle_group,
  equipment = EXCLUDED.equipment,
  instructions = EXCLUDED.instructions,
  video_url = EXCLUDED.video_url,
  tracking_type = EXCLUDED.tracking_type;
