INSERT INTO exercises (id, name, category, muscle_group, equipment, instructions, video_url, tracking_type)
VALUES
  ('ex-panca-piana', 'Panca Piana con Bilanciere', 'Petto', 'Pettorali', 'Bilanciere', 'Sdraiati sulla panca piana con piedi ben saldi a terra. Afferra il bilanciere poco più largo delle spalle. Abbassa la sbarra allo sterno adducendo le scapole e spingi in alto.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-panca-inclinata-bil', 'Panca Inclinata con Bilanciere', 'Petto', 'Pettorali', 'Bilanciere', 'Panca a 30°-45°. Impugna il bilanciere e scendi controllando la traiettoria verso la parte alta del petto (clavicolare), quindi distendi le braccia.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-panca-declinata-bil', 'Panca Declinata con Bilanciere', 'Petto', 'Pettorali', 'Bilanciere', 'Panca declinata a 15°-30°. Focalizza il lavoro sui fasci inferiori del grande pettorale, discesa controllata alla base dello sterno.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-spinte-manubri-piana', 'Spinte con Manubri su Panca Piana', 'Petto', 'Pettorali', 'Manubri', 'Disteso su panca piana, spingi i manubri verso l''alto garantendo un arco di movimento ampio con massimo allungamento in basso.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-spinte-manubri-inclinata', 'Spinte con Manubri su Panca Inclinata', 'Petto', 'Pettorali', 'Manubri', 'Panca inclinata a 30°. Gomiti leggermente chiusi a 45°-60° rispetto al busto, spingi i manubri in convergenza senza farli toccare.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-spinte-manubri-declinata', 'Spinte con Manubri su Panca Declinata', 'Petto', 'Pettorali', 'Manubri', 'Isola i fasci sternocostali inferiori con massima escursione articolare e sicurezza per le cuffie dei rotatori.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-chest-press-macchina', 'Chest Press (Macchina)', 'Petto', 'Pettorali', 'Macchina', 'Regola l''altezza del sellino in modo che le impugnature siano all''altezza del centro del petto. Spingi in avanti mantenendo le scapole incollate allo schienale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-chest-press-inclinata', 'Incline Chest Press (Macchina)', 'Petto', 'Pettorali', 'Macchina', 'Traiettoria convergente guidata mirata al fascio clavicolare del pettorale con tensione costante.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-croci-manubri-piana', 'Croci con Manubri su Panca Piana', 'Petto', 'Pettorali', 'Manubri', 'Gomiti leggermente flessi ad angolo fisso. Apri le braccia inspirando fino al massimo allungamento pettorale, richiudi espirando.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-croci-manubri-inclinata', 'Croci con Manubri su Panca Inclinata', 'Petto', 'Pettorali', 'Manubri', 'Enfasi sull''allungamento della parte superiore del petto. Mantieni il petto in fuori e le spalle basse e retratte.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-croci-cavi-alti', 'Croci ai Cavi Alti (Crossover)', 'Petto', 'Pettorali', 'Cavi', 'Posizionati al centro della torretta cavi, inclina leggermente il busto in avanti. Conduci i cavi verso il basso e l''avanti incrociando leggermente le mani.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-croci-cavi-bassi', 'Croci ai Cavi Bassi', 'Petto', 'Pettorali', 'Cavi', 'Cavi posizionati in basso. Porta le maniglie verso l''alto e verso l''interno all''altezza del mento con traiettoria a semicerchio.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-croci-cavi-medi', 'Croci ai Cavi su Panca Piana', 'Petto', 'Pettorali', 'Cavi', 'Posiziona una panca tra i cavi. Permette una tensione muscolare continua lungo l''intero arco di movimento.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-pectoral-machine', 'Pectoral Machine (Pec Deck)', 'Petto', 'Pettorali', 'Macchina', 'Seduto dritto, avambracci o mani sulle imbottiture. Chiudi le braccia stringendo intensamente il petto per 1 secondo al picco di contrazione.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-dip-parallele-petto', 'Dip alle Parallele (Focus Petto)', 'Petto', 'Pettorali', 'Niente', 'Impugna le sbarre, inclina il busto a 30° in avanti con gomiti leggermente aperti per spostare il focus dal tricipite al grande pettorale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-piegamenti-terra', 'Piegamenti sulle Braccia (Push-Up)', 'Petto', 'Pettorali', 'Niente', 'Mani a terra poco più larghe delle spalle, core contratto a tavola. Scendi fino a sfiorare il pavimento con il petto e risali.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-pushup-declinati', 'Push-Up con Piedi Rialzati', 'Petto', 'Pettorali', 'Niente', 'Posiziona i piedi su una panca o rialzo. Aumenta il carico percepito e stimola con intensità i fasci superiori del pettorale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-pullover-manubrio', 'Pullover con Manubrio', 'Petto', 'Pettorali', 'Manubri', 'Disteso trasversalmente sulla panca, impugna un manubrio a due mani a calice. Abbassa lentamente dietro la testa espandendo la cassa toracica.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-panca-smith', 'Panca Piana al Multipower (Smith Machine)', 'Petto', 'Pettorali', 'Macchina', 'Guida rigida che consente di spingere carichi massimali in sicurezza senza richiedere stabilizzazione laterale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-panca-inclinata-smith', 'Panca Inclinata al Multipower (Smith Machine)', 'Petto', 'Pettorali', 'Macchina', 'Focus sul fascio clavicolare con traiettoria fissa per un sovraccarico progressivo controllato.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-svend-press', 'Svend Press con Disco', 'Petto', 'Pettorali', 'Disco', 'Stringi uno o due dischi tra i palmi delle mani davanti al petto ed estendi le braccia mantenendo la massima pressione isometrica.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-landmine-chest-press', 'Landmine Chest Press', 'Petto', 'Pettorali', 'Bilanciere', 'Impugna l''estremità libera di un bilanciere ancorato e spingi diagonalmente in avanti e verso l''alto attivando la porzione alta del petto.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-bench-press-with-barbell-close-up-40321-large.mp4', 'weight_reps'),
  ('ex-stacco-terra', 'Stacco da Terra con Bilanciere (Deadlift)', 'Dorso', 'Dorsali', 'Bilanciere', 'Piedi a larghezza bacino, schiena neutra. Afferra il bilanciere, spingi con i talloni estendendo contemporaneamente ginocchia e anche.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-trazioni-prona', 'Trazioni alla Sbarra (Pull-Up Presa Prona)', 'Dorso', 'Dorsali', 'Niente', 'Impugna la sbarra a presa prona più larga delle spalle. Traziona fino a portare il mento sopra la sbarra deprimendo le scapole.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-trazioni-supina', 'Trazioni alla Sbarra (Chin-Up Presa Supina)', 'Dorso', 'Dorsali', 'Niente', 'Presa supina a larghezza spalle. Coinvolge con forza il gran dorsale e il bicipite brachiale durante la trazione.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-trazioni-neutra', 'Trazioni Presa Neutra', 'Dorso', 'Dorsali', 'Niente', 'Impugnatura a presa parallela. Riduce lo stress articolare su polsi e spalle consentendo grande sviluppo di spessore dorsale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-lat-pulldown-cavo', 'Lat Pulldown (Cavo)', 'Dorso', 'Dorsali', 'Cavi', 'Seduto alla lat machine, blocca le cosce sotto i cuscinetti. Tira la barra verso la parte alta dello sterno inclinando leggermente il busto.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-lat-machine-inversa', 'Lat Machine Presa Inversa (Supina)', 'Dorso', 'Dorsali', 'Cavi', 'Presa supina a larghezza spalle. Enfatizza il lavoro sulle fibre inferiori del gran dorsale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-lat-machine-triangolo', 'Lat Machine con Presa a Triangolo', 'Dorso', 'Dorsali', 'Cavi', 'Presa stretta neutra. Traziona verso il petto tirando con i gomiti stretti lungo i fianchi.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-lat-pulldown-dritte', 'Lat Pulldown Braccia Dritte (Cavo)', 'Dorso', 'Dorsali', 'Cavi', 'In piedi davanti al cavo alto, gomiti quasi tesi. Abbassa la barra fino alle cosce attivando esclusivamente i dorsali in isolamento.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-rematore-bilanciere', 'Rematore con Bilanciere (Barbell Row)', 'Dorso', 'Dorsali', 'Bilanciere', 'Busto flesso in avanti a 45°-60°, schiena compatta. Tira il bilanciere verso l''ombelico stringendo le scapole al massimo.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-rematore-pendlay', 'Pendlay Row con Bilanciere', 'Dorso', 'Dorsali', 'Bilanciere', 'Busto parallelo al suolo a 90°. Ogni ripetizione riparte da fermo dal pavimento con trazione esplosiva al petto.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-rematore-manubrio', 'Rematore con Manubrio Singolo', 'Dorso', 'Dorsali', 'Manubri', 'Ginocchio e mano in appoggio su panca. Tira il manubrio verso l''anca mantenendo il busto fermo e adducendo la scapola.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-rematore-macchina', 'Rematore Alto Convergente (Macchina)', 'Dorso', 'Dorsali', 'Macchina', 'Seduto con petto contro il cuscino, tira le impugnature verso il busto mantenendo i gomiti alti per colpire trapezio e gran dorsale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-pulley-basso', 'Pulley Basso al Cavo', 'Dorso', 'Dorsali', 'Cavi', 'Seduto con gambe leggermente piegate, busto eretto. Tira il triangolo verso l''ombelico aprendo il petto e contraendo i dorsali.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-pulley-larga', 'Pulley Basso Presa Larga Prona', 'Dorso', 'Dorsali', 'Cavi', 'Usa una barra dritta con presa prona larga per spostare il focus sullo spessore del trapezio medio e romboidi.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-t-bar-row', 'T-Bar Row con Supporto Petto', 'Dorso', 'Dorsali', 'Macchina', 'Petto in appoggio su panca inclinata, afferra le maniglie a presa neutra e traziona verso l''alto senza sovraccaricare la zona lombare.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-seal-row', 'Seal Row su Panca Orizzontale', 'Dorso', 'Dorsali', 'Bilanciere', 'Sdraiato a pancia in giù su panca rialzata, tira il bilanciere fino a toccare il fondo della panca annullando qualsiasi slancio corporeo.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-face-pull', 'Face Pull ai Cavi con Corda', 'Dorso', 'Trapezi', 'Cavi', 'Cavo posizionato all''altezza degli occhi, impugna la corda e tira verso la fronte extraruotando le spalle per rinforzare deltoide posteriore e cuffia.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-shrug-bilanciere', 'Shrug con Bilanciere (Scrollate)', 'Dorso', 'Trapezi', 'Bilanciere', 'In piedi, braccia distese. Eleva le spalle verso le orecchie contraendo intensamente i trapezi superiori senza ruotare le spalle.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-shrug-manubri', 'Shrug con Manubri', 'Dorso', 'Trapezi', 'Manubri', 'Manubri lungo i fianchi a presa neutra. Solleva le spalle con movimento verticale puro trattenendo la contrazione per 1 secondo.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-hyperextension-lombari', 'Iperestensioni Lombari (Panca a 45°)', 'Dorso', 'Lombari', 'Niente', 'Bacino bloccato sull''imbottitura. Fletti il busto verso il basso e risali estendendo la colonna fino alla linea neutra con il corpo.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-good-morning', 'Good Morning con Bilanciere', 'Dorso', 'Lombari', 'Bilanciere', 'Bilanciere sui trapezi, ginocchia sbloccate. Spingi il bacino indietro flettendo il busto in avanti mantenendo la schiena lombare perfettamente estesa.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-stacco-trap-bar', 'Stacco con Trap Bar (Hex Bar Deadlift)', 'Dorso', 'Dorsali', 'Bilanciere', 'Posizionati all''interno della trap bar. La presa neutra e il baricentro allineato riducono il momento torcente sulla colonna lombare.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-rematore-cavo-singolo', 'Rematore Unilaterale al Cavo Basso', 'Dorso', 'Dorsali', 'Cavi', 'Esegui il rematore con un braccio alla volta per massimizzare la torsione controllata e l''allungamento laterale del gran dorsale.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-pullover-cavi', 'Pullover al Cavo con Corda', 'Dorso', 'Dorsali', 'Cavi', 'Ginocchia a terra o in piedi con busto inclinato. Porta la corda dalle spalle fino ai fianchi aprendola al termine del movimento.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-pull-ups-40322-large.mp4', 'weight_reps'),
  ('ex-squat-bilanciere', 'Squat con Bilanciere (Back Squat)', 'Gambe', 'Quadricipiti', 'Bilanciere', 'Bilanciere sui trapezi, piedi larghezza spalle con punte leggermente aperte. Scendi fino a rompere il parallelo e risali spingendo sui talloni.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-front-squat', 'Front Squat con Bilanciere', 'Gambe', 'Quadricipiti', 'Bilanciere', 'Bilanciere posizionato sui deltoidi anteriori con gomiti alti. Il busto rimane molto più eretto caricando fortemente i quadricipiti.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-leg-press-45', 'Leg Press a 45°', 'Gambe', 'Quadricipiti', 'Macchina', 'Schiena e glutei ben aderenti al sedile. Piedi a larghezza spalle sulla pedana. Scendi controllando il carico senza staccare l''osso sacro.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-hack-squat', 'Hack Squat (Macchina)', 'Gambe', 'Quadricipiti', 'Macchina', 'Spalle sotto i cuscini, schiena aderente. Scendi fino a formare un angolo di 90° o inferiore alle ginocchia con massimo stimolo quadricipitale.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-leg-extension', 'Leg Extension (Macchina)', 'Gambe', 'Quadricipiti', 'Macchina', 'Regola il rullo sopra le caviglie e l''asse del ginocchio allineato al fulcro. Estendi le gambe contraendo al massimo il quadricipite.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-bulgarian-split-squat', 'Bulgarian Split Squat con Manubri', 'Gambe', 'Glutei', 'Manubri', 'Un piede poggiato indietro su panca, l''altro avanti. Scendi verticalmente caricando il gluteo e quadricipite della gamba anteriore.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-affondi-camminati', 'Affondi Camminati con Manubri', 'Gambe', 'Quadricipiti', 'Manubri', 'Fai un passo avanti flettendo entrambe le ginocchia a 90°. Spingi con la gamba anteriore per avanzare con l''altra gamba.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-affondi-indietro', 'Affondi all''Indietro (Reverse Lunge)', 'Gambe', 'Glutei', 'Manubri', 'Fai un passo indietro piegando il ginocchio a sfiorare il suolo. Più sicuro per l''articolazione del ginocchio rispetto agli affondi frontali.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-goblet-squat', 'Goblet Squat con Manubrio o Kettlebell', 'Gambe', 'Quadricipiti', 'Manubri', 'Sostieni il carico aderente al petto. Mantieni il busto alto e scendi in accosciata profonda allargando le ginocchia.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-hip-thrust', 'Hip Thrust con Bilanciere', 'Gambe', 'Glutei', 'Bilanciere', 'Dorso in appoggio su panca, bilanciere protetto sul bacino. Estendi le anche verso l''alto contraendo ferocemente i glutei in cima.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-glute-bridge', 'Glute Bridge a Terra', 'Gambe', 'Glutei', 'Niente', 'Sdraiati supino con ginocchia flesse e piedi a terra. Solleva il bacino allineando cosce e busto stringendo i glutei.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
  ('ex-stacco-rumeno-bil', 'Stacco Rumeno con Bilanciere (RDL)', 'Gambe', 'Femorali', 'Bilanciere', 'Ginocchia appena piegate. Spingi il bacino indietro scivolando il bilanciere lungo le cosce fino a sentire forte allungamento sui femorali.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-stacco-rumeno-man', 'Stacco Rumeno con Manubri', 'Gambe', 'Femorali', 'Manubri', 'Manubri davanti alle cosce. Discesa lenta e controllata arretrando il sedere, schiena dritta con scapole addotte.', 'https://assets.mixkit.co/videos/preview/mixkit-man-doing-deadlifts-with-a-barbell-in-a-gym-40323-large.mp4', 'weight_reps'),
  ('ex-leg-curl-sdraiato', 'Leg Curl Sdraiato (Macchina)', 'Gambe', 'Femorali', 'Macchina', 'Sdraiati prono con il cuscinetto dietro le caviglie. Fletti le gambe portando i talloni verso i glutei senza sollevare il bacino.', 'https://assets.mixkit.co/videos/preview/mixkit-woman-doing-squats-with-a-barbell-40324-large.mp4', 'weight_reps'),
